package com.mylibrary.library;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication
public class MyLibraryApplication {
    public static void main(String[] args) {
        SpringApplication.run(MyLibraryApplication.class, args);
    }
}

package com.mylibrary.library.controller;

import com.mylibrary.library.entities.Categoria;
import com.mylibrary.library.service.CategoriaService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/categorias")
public class CategoriaController {
    private final CategoriaService service;

    public CategoriaController(CategoriaService service) { this.service = service; }

    @GetMapping
    public List<Categoria> listar() { return service.listar(); }

    @PostMapping
    public ResponseEntity<?> criar(@RequestBody Categoria c) {
        try {
            Categoria saved = service.criar(c);
            return ResponseEntity.ok(saved);
        } catch (IllegalArgumentException ex) {
            return ResponseEntity.badRequest().body(ex.getMessage());
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<?> excluir(@PathVariable Long id) {
        try {
            service.excluir(id);
            return ResponseEntity.noContent().build();
        } catch (IllegalStateException | IllegalArgumentException ex) {
            return ResponseEntity.badRequest().body(ex.getMessage());
        }
    }
}

package com.mylibrary.library.controller;

import com.mylibrary.library.entities.Emprestimo;
import com.mylibrary.library.entities.Livro;
import com.mylibrary.library.repository.EmprestimoRepository;
import com.mylibrary.library.repository.LivroRepository;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {
    private final LivroRepository livroRepo;
    private final EmprestimoRepository empreRepo;

    public DashboardController(LivroRepository livroRepo, EmprestimoRepository empreRepo) {
        this.livroRepo = livroRepo; this.empreRepo = empreRepo;
    }

    @GetMapping
    public Map<String, Object> stats() {
        List<Livro> all = livroRepo.findAll();
        long total = all.size();
        long disponiveis = all.stream().filter(l -> l.getStatus() != null && l.getStatus().name().equals("DISPONIVEL")).count();
        long emprestados = all.stream().filter(l -> l.getStatus() != null && l.getStatus().name().equals("EMPRESTADO")).count();
        List<Emprestimo> ativos = empreRepo.findByDataDevolucaoEfetivaIsNull();

        Map<String, Object> m = new HashMap<>();
        m.put("totalLivros", total);
        m.put("livrosDisponiveis", disponiveis);
        m.put("livrosEmprestados", emprestados);
        m.put("emprestimosAtivos", ativos.size());
        m.put("ultimosEmprestimos", empreRepo.findAll().stream().sorted((a,b)->b.getDataEmprestimo().compareTo(a.getDataEmprestimo())).limit(5).toList());
        return m;
    }
}

package com.mylibrary.library.controller;

import com.mylibrary.library.entities.Emprestimo;
import com.mylibrary.library.service.EmprestimoService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/emprestimos")
public class EmprestimoController {
    private final EmprestimoService service;

    public EmprestimoController(EmprestimoService service) { this.service = service; }

    @GetMapping
    public List<Emprestimo> listarTodos() { return service.listarAtivos(); }

    @GetMapping("/ativos")
    public List<Emprestimo> listarAtivos() { return service.listarAtivos(); }

    @GetMapping("/atrasados")
    public List<Emprestimo> listarAtrasados() { return service.listarAtrasados(); }

    @PostMapping("/emprestar")
    public ResponseEntity<?> emprestar(@RequestParam Long livroId, @RequestBody Emprestimo e) {
        try { return ResponseEntity.ok(service.emprestar(livroId, e)); }
        catch (IllegalStateException | IllegalArgumentException ex) { return ResponseEntity.badRequest().body(ex.getMessage()); }
    }

    @PostMapping("/{id}/devolver")
    public ResponseEntity<?> devolver(@PathVariable Long id) {
        try { return ResponseEntity.ok(service.devolver(id)); }
        catch (IllegalStateException | IllegalArgumentException ex) { return ResponseEntity.badRequest().body(ex.getMessage()); }
    }

    @GetMapping("/livro/{livroId}")
    public List<com.mylibrary.library.entities.Emprestimo> historicoPorLivro(@PathVariable Long livroId) {
        return service.historicoPorLivro(livroId);
    }

}

package com.mylibrary.library.controller;

import com.mylibrary.library.entities.Livro;
import com.mylibrary.library.enums.StatusLivro;
import com.mylibrary.library.service.LivroService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/api/livros")
public class LivroController {
    private final LivroService service;

    public LivroController(LivroService service) { this.service = service; }

    @GetMapping
    public List<Livro> listar(@RequestParam(required = false) Long categoriaId,
                              @RequestParam(required = false) StatusLivro status,
                              @RequestParam(required = false) String q) {
        return service.listar(categoriaId, status, q);
    }

    @GetMapping("/{id}")
    public ResponseEntity<?> buscar(@PathVariable Long id) {
        try { return ResponseEntity.ok(service.buscar(id)); }
        catch (IllegalArgumentException ex) { return ResponseEntity.notFound().build(); }
    }

    @PostMapping
    public ResponseEntity<?> criar(@RequestBody Livro l) {
        Livro saved = service.criar(l);
        return ResponseEntity.ok(saved);
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<?> excluir(@PathVariable Long id) {
        try { service.excluir(id); return ResponseEntity.noContent().build(); }
        catch (IllegalStateException | IllegalArgumentException ex) { return ResponseEntity.badRequest().body(ex.getMessage()); }
    }

}

package com.mylibrary.library.entities;

import jakarta.persistence.*;
import java.util.ArrayList;
import java.util.List;

@Entity
public class Categoria {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(unique = true, nullable = false)
    private String nome;

    private String descricao;

    @OneToMany(mappedBy = "categoria", cascade = CascadeType.ALL)
    private List<Livro> livros = new ArrayList<>();

    // getters e setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getNome() { return nome; }
    public void setNome(String nome) { this.nome = nome; }
    public String getDescricao() { return descricao; }
    public void setDescricao(String descricao) { this.descricao = descricao; }
    public List<Livro> getLivros() { return livros; }
    public void setLivros(List<Livro> livros) { this.livros = livros; }
}

package com.mylibrary.library.entities;

import jakarta.persistence.*;
import java.time.LocalDate;

@Entity
public class Emprestimo {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ManyToOne
    @JoinColumn(name = "livro_id")
    private Livro livro;

    private String nomePessoa;
    private String telefone;

    private LocalDate dataEmprestimo;
    private LocalDate dataDevolucaoPrevista;
    private LocalDate dataDevolucaoEfetiva;

    // getters/setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Livro getLivro() { return livro; }
    public void setLivro(Livro livro) { this.livro = livro; }
    public String getNomePessoa() { return nomePessoa; }
    public void setNomePessoa(String nomePessoa) { this.nomePessoa = nomePessoa; }
    public String getTelefone() { return telefone; }
    public void setTelefone(String telefone) { this.telefone = telefone; }
    public LocalDate getDataEmprestimo() { return dataEmprestimo; }
    public void setDataEmprestimo(LocalDate dataEmprestimo) { this.dataEmprestimo = dataEmprestimo; }
    public LocalDate getDataDevolucaoPrevista() { return dataDevolucaoPrevista; }
    public void setDataDevolucaoPrevista(LocalDate dataDevolucaoPrevista) { this.dataDevolucaoPrevista = dataDevolucaoPrevista; }
    public LocalDate getDataDevolucaoEfetiva() { return dataDevolucaoEfetiva; }
    public void setDataDevolucaoEfetiva(LocalDate dataDevolucaoEfetiva) { this.dataDevolucaoEfetiva = dataDevolucaoEfetiva; }
}

package com.mylibrary.library.entities;

import com.mylibrary.library.enums.StatusLivro;
import jakarta.persistence.*;

@Entity
public class Livro {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String titulo;
    private String autor;
    private String isbn;
    private Integer ano;

    @Enumerated(EnumType.STRING)
    private StatusLivro status = StatusLivro.DISPONIVEL;

    @ManyToOne
    @JoinColumn(name = "categoria_id")
    private Categoria categoria;

    // getters / setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getTitulo() { return titulo; }
    public void setTitulo(String titulo) { this.titulo = titulo; }
    public String getAutor() { return autor; }
    public void setAutor(String autor) { this.autor = autor; }
    public String getIsbn() { return isbn; }
    public void setIsbn(String isbn) { this.isbn = isbn; }
    public Integer getAno() { return ano; }
    public void setAno(Integer ano) { this.ano = ano; }
    public StatusLivro getStatus() { return status; }
    public void setStatus(StatusLivro status) { this.status = status; }
    public Categoria getCategoria() { return categoria; }
    public void setCategoria(Categoria categoria) { this.categoria = categoria; }
}

package com.mylibrary.library.enums;

public enum StatusLivro {
    DISPONIVEL,
    EMPRESTADO
}

package com.mylibrary.library.repository;

import com.mylibrary.library.entities.Categoria;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.Optional;

public interface CategoriaRepository extends JpaRepository<Categoria, Long> {
    Optional<Categoria> findByNome(String nome);
}

package com.mylibrary.library.repository;

import com.mylibrary.library.entities.Emprestimo;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import java.time.LocalDate;
import java.util.List;

public interface EmprestimoRepository extends JpaRepository<Emprestimo, Long> {
    List<Emprestimo> findByDataDevolucaoEfetivaIsNull();

    @Query("select e from Emprestimo e where e.dataDevolucaoPrevista < :hoje and e.dataDevolucaoEfetiva is null")
    List<Emprestimo> findAtrasados(LocalDate hoje);

    List<Emprestimo> findByLivroId(Long livroId);
}

package com.mylibrary.library.repository;

import com.mylibrary.library.entities.Livro;
import com.mylibrary.library.enums.StatusLivro;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface LivroRepository extends JpaRepository<Livro, Long> {
    List<Livro> findByCategoriaId(Long categoriaId);
    List<Livro> findByStatus(StatusLivro status);

    @Query("select l from Livro l where (:categoriaId is null or l.categoria.id = :categoriaId) " +
            "and (:status is null or l.status = :status) " +
            "and ( (:q is null) or lower(l.titulo) like lower(concat('%',:q,'%')) or lower(l.autor) like lower(concat('%',:q,'%')) )")
    List<Livro> filter(@Param("categoriaId") Long categoriaId, @Param("status") StatusLivro status, @Param("q") String q);
}

package com.mylibrary.library.service;

import com.mylibrary.library.entities.Categoria;
import com.mylibrary.library.repository.CategoriaRepository;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class CategoriaService {
    private final CategoriaRepository repo;

    public CategoriaService(CategoriaRepository repo) { this.repo = repo; }

    public List<Categoria> listar() { return repo.findAll(); }

    public Categoria criar(Categoria c) {
        repo.findByNome(c.getNome()).ifPresent(existing -> { throw new IllegalArgumentException("Nome de categoria já existe"); });
        return repo.save(c);
    }

    public void excluir(Long id) {
        Categoria c = repo.findById(id).orElseThrow(() -> new IllegalArgumentException("Categoria não encontrada"));
        if (c.getLivros() != null && !c.getLivros().isEmpty()) throw new IllegalStateException("Categoria possui livros vinculados");
        repo.delete(c);
    }
}

package com.mylibrary.library.service;

import com.mylibrary.library.entities.Emprestimo;
import com.mylibrary.library.entities.Livro;
import com.mylibrary.library.enums.StatusLivro;
import com.mylibrary.library.repository.EmprestimoRepository;
import com.mylibrary.library.repository.LivroRepository;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.util.List;

@Service
public class EmprestimoService {
    private final EmprestimoRepository empreRepo;
    private final LivroRepository livroRepo;

    public EmprestimoService(EmprestimoRepository empreRepo, LivroRepository livroRepo) {
        this.empreRepo = empreRepo; this.livroRepo = livroRepo;
    }

    public Emprestimo emprestar(Long livroId, Emprestimo e) {
        Livro l = livroRepo.findById(livroId).orElseThrow(() -> new IllegalArgumentException("Livro não encontrado"));
        if (l.getStatus() != StatusLivro.DISPONIVEL) throw new IllegalStateException("Livro já está emprestado");
        e.setLivro(l);
        e.setDataEmprestimo(LocalDate.now());
        Emprestimo saved = empreRepo.save(e);
        l.setStatus(StatusLivro.EMPRESTADO);
        livroRepo.save(l);
        return saved;
    }

    public Emprestimo devolver(Long emprestimoId) {
        Emprestimo e = empreRepo.findById(emprestimoId).orElseThrow(() -> new IllegalArgumentException("Empréstimo não encontrado"));
        if (e.getDataDevolucaoEfetiva() != null) throw new IllegalStateException("Empréstimo já devolvido");
        Livro l = e.getLivro();
        if (l.getStatus() != StatusLivro.EMPRESTADO) throw new IllegalStateException("Livro não está emprestado");
        e.setDataDevolucaoEfetiva(LocalDate.now());
        empreRepo.save(e);
        l.setStatus(StatusLivro.DISPONIVEL);
        livroRepo.save(l);
        return e;
    }

    public List<Emprestimo> listarAtivos() { return empreRepo.findByDataDevolucaoEfetivaIsNull(); }

    public List<Emprestimo> listarAtrasados() { return empreRepo.findAtrasados(LocalDate.now()); }

    public List<Emprestimo> historicoPorLivro(Long livroId) { return empreRepo.findByLivroId(livroId); }
}

package com.mylibrary.library.service;

import com.mylibrary.library.entities.Livro;
import com.mylibrary.library.enums.StatusLivro;
import com.mylibrary.library.repository.LivroRepository;
import org.springframework.stereotype.Service;

import java.util.List;

@Service
public class LivroService {
    private final LivroRepository repo;

    public LivroService(LivroRepository repo) { this.repo = repo; }

    public Livro criar(Livro l) {
        l.setStatus(StatusLivro.DISPONIVEL);
        return repo.save(l);
    }

    public List<Livro> listar(Long categoriaId, StatusLivro status, String q) {
        return repo.filter(categoriaId, status, q);
    }

    public Livro buscar(Long id) { return repo.findById(id).orElseThrow(() -> new IllegalArgumentException("Livro não encontrado")); }

    public void excluir(Long id) {
        Livro l = buscar(id);
        if (l.getStatus() != StatusLivro.DISPONIVEL) throw new IllegalStateException("Só é possível excluir livro disponível");
        repo.delete(l);
    }
}

{
  "$schema": "./node_modules/@angular/cli/lib/config/schema.json",
  "version": 1,
  "cli": {
    "packageManager": "npm"
  },
  "newProjectRoot": "projects",
  "projects": {
    "mylibrary": {
      "projectType": "application",
      "schematics": {},
      "root": "",
      "sourceRoot": "src",
      "prefix": "app",
      "architect": {
        "build": {
          "builder": "@angular/build:application",
          "options": {
            "browser": "src/main.ts",
            "tsConfig": "tsconfig.app.json",
            "assets": [
              {
                "glob": "**/*",
                "input": "public"
              }
            ],
            "styles": [
              "src/styles.css"
            ]
          },
          "configurations": {
            "production": {
              "budgets": [
                {
                  "type": "initial",
                  "maximumWarning": "500kB",
                  "maximumError": "1MB"
                },
                {
                  "type": "anyComponentStyle",
                  "maximumWarning": "4kB",
                  "maximumError": "8kB"
                }
              ],
              "outputHashing": "all"
            },
            "development": {
              "optimization": false,
              "extractLicenses": false,
              "sourceMap": true
            }
          },
          "defaultConfiguration": "production"
        },
        "serve": {
          "builder": "@angular/build:dev-server",
          "configurations": {
            "production": {
              "buildTarget": "mylibrary:build:production"
            },
            "development": {
              "buildTarget": "mylibrary:build:development"
            }
          },
          "defaultConfiguration": "development"
        },
        "test": {
          "builder": "@angular/build:unit-test"
        }
      }
    }
  }
}

{
  "extends": "./tsconfig.json",
  "compilerOptions": {
    "outDir": "./out-tsc/app",
    "types": []
  },
  "include": [
    "src/**/*.ts"
  ],
  "exclude": [
    "src/**/*.spec.ts"
  ]
}
